CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.retained_price_stage_v3(p_attempt uuid,p_token text)
RETURNS jsonb LANGUAGE plpgsql SET search_path TO 'pg_catalog' SET "TimeZone" TO 'UTC'
AS $body$
DECLARE tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;m population_top3000_202608_202609_v1.retained_price_partition_v1%rowtype;ex population_top3000_202608_202609_v1.retained_price_expectation_v2%rowtype;c record;d record;n bigint;source_n bigint;mismatch_n bigint;hash_n bigint;identity_n bigint;scope_n bigint;duplicate_n bigint;flags_n bigint;retained_n bigint;null_n bigint;raw_digest text;out_digest text;first_bar timestamptz;last_bar timestamptz;lo timestamptz;hi timestamptz;normalizer_hash text;summary jsonb;key text;
BEGIN
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid;
 IF t.family_id IS DISTINCT FROM 'P02' OR t.stage NOT IN('DERIVE','VALIDATE') OR t.payload->>'kind' IS DISTINCT FROM 'RETAINED_ALPACA_AUGUST_SESSION' OR t.payload->>'normalization_route' IS DISTINCT FROM 'RETAINED_PRICE_NORMALIZE_V2' OR t.payload->>'session_label' IS DISTINCT FROM 'premarket' THEN RAISE EXCEPTION 'RETAINED_STAGE_V3_SCOPE_MISMATCH';END IF;
 normalizer_hash:=encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.retained_price_normalize_v2(uuid,text)'::regprocedure),'UTF8')),'hex');
 IF normalizer_hash IS DISTINCT FROM '0c9caf459397b6e1ff65de27c1897af6b2865638cfd9c596bc8b67494ec9fd39' THEN RAISE EXCEPTION 'RETAINED_STAGE_V3_NORMALIZER_CHANGED';END IF;
 SELECT * INTO STRICT m FROM population_top3000_202608_202609_v1.retained_price_partition_v1 WHERE family_id=t.family_id AND partition_key=t.partition_key AND input_versions=t.input_versions;
 IF m.session_label IS DISTINCT FROM 'premarket' OR m.observed_rows NOT BETWEEN 1 AND 1440 OR m.session_date NOT BETWEEN DATE '2026-08-01' AND DATE '2026-08-31' OR m.checks->>'structural_state' IS DISTINCT FROM 'OBSERVED_ROWS_STRUCTURALLY_VALID' OR m.source_relation_oid IS DISTINCT FROM 'market_fixed_20250901_20260831.alpaca_sip_bars_1m_202608'::regclass::oid THEN RAISE EXCEPTION 'RETAINED_STAGE_V3_MANIFEST_INVALID';END IF;
 SELECT * INTO STRICT ex FROM population_top3000_202608_202609_v1.retained_price_expectation_v2 WHERE manifest_id=m.manifest_id;
 SELECT company_id,anchor_ticker,selection_order INTO STRICT c FROM population_top3000_202608_202609_v1.working_accepted_companies_v1 WHERE company_id=ex.company_id;
 SELECT point_source_state,identity_record_sha256 INTO STRICT d FROM population_top3000_202608_202609_v1.d02_anchor_source_point_v2 WHERE company_ordinal=c.selection_order AND session_date=m.session_date;
 IF d.point_source_state IS DISTINCT FROM 'VERIFIED_POINT_AND_SOURCE_LINK' OR d.identity_record_sha256 IS NULL OR ex.session_date IS DISTINCT FROM m.session_date OR ex.session_label IS DISTINCT FROM m.session_label OR ex.observed_bars IS DISTINCT FROM m.observed_rows OR ex.normalization_sha256 IS DISTINCT FROM normalizer_hash THEN RAISE EXCEPTION 'RETAINED_STAGE_V3_DATED_BINDING_CHANGED';END IF;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_dependency dep JOIN population_top3000_202608_202609_v1.pipeline_task prior ON prior.task_id=dep.prerequisite_task_id WHERE dep.task_id=tid AND prior.family_id=t.family_id AND prior.partition_key=t.partition_key AND prior.input_versions=t.input_versions AND prior.status='COMPLETE' AND prior.stage=CASE t.stage WHEN 'DERIVE' THEN 'NORMALIZE' ELSE 'DERIVE' END) THEN RAISE EXCEPTION 'RETAINED_STAGE_V3_PREDECESSOR_NOT_COMPLETE';END IF;
 lo:=(m.session_date+TIME '04:00') AT TIME ZONE 'America/New_York';
 SELECT regular_open_utc INTO STRICT hi FROM population_top3000_202608_202609_v1.catalog_calendar WHERE scope_id=t.payload->>'calendar_scope_id' AND session_date=m.session_date AND source_record_sha256=t.input_versions->>'calendar_record_sha256' AND source_receipt_sha256=t.input_versions->>'calendar_receipt_sha256';
 PERFORM population_top3000_202608_202609_v1.alpaca_sip_resource_guard_v2();
 WITH checked AS MATERIALIZED(SELECT o.*,b.bar_ts AS raw_ts,(float8send(o.open),float8send(o.high),float8send(o.low),float8send(o.close),o.volume,o.trade_count,float8send(o.vwap)) IS DISTINCT FROM (float8send(b.open),float8send(b.high),float8send(b.low),float8send(b.close),b.volume,b.trade_count,float8send(b.vwap)) AS bad_values,encode(sha256(convert_to(jsonb_build_array(b.instrument_key,extract(epoch FROM b.bar_ts),b.session_label::text,encode(float8send(b.open),'hex'),encode(float8send(b.high),'hex'),encode(float8send(b.low),'hex'),encode(float8send(b.close),'hex'),b.volume,b.trade_count,encode(float8send(b.vwap),'hex'),b.loaded_by_job_id,extract(epoch FROM b.source_loaded_at))::text,'UTF8')),'hex') AS actual_row_hash FROM population_top3000_202608_202609_v1.retained_price_observation_v2 o LEFT JOIN market_fixed_20250901_20260831.alpaca_sip_bars_1m_202608 b ON b.instrument_key=o.instrument_key AND b.bar_ts=o.bar_ts WHERE o.manifest_id=m.manifest_id)
 SELECT count(*),count(raw_ts),count(*) FILTER(WHERE bad_values),count(*) FILTER(WHERE source_row_sha256 IS DISTINCT FROM actual_row_hash),count(*) FILTER(WHERE company_id IS DISTINCT FROM c.company_id OR source_symbol IS DISTINCT FROM c.anchor_ticker OR identity_record_sha256 IS DISTINCT FROM encode(d.identity_record_sha256,'hex') OR source_manifest_sha256 IS DISTINCT FROM m.manifest_sha256 OR normalization_sha256 IS DISTINCT FROM normalizer_hash),count(*) FILTER(WHERE instrument_key IS DISTINCT FROM m.instrument_key OR session_date IS DISTINCT FROM m.session_date OR session_label IS DISTINCT FROM m.session_label OR bar_ts<lo OR bar_ts>=hi OR bar_ts<>date_trunc('minute',bar_ts)),count(*)-count(DISTINCT bar_ts),count(*) FILTER(WHERE lineage->>'family_accepted' IS DISTINCT FROM 'false' OR lineage->>'original_historical_receipt_verified' IS DISTINCT FROM 'false' OR lineage->>'independent_economic_accuracy_verified' IS DISTINCT FROM 'false'),count(*) FILTER(WHERE open IS NULL OR high IS NULL OR low IS NULL OR close IS NULL OR volume IS NULL OR trade_count IS NULL OR vwap IS NULL),min(bar_ts),max(bar_ts),encode(sha256(convert_to(string_agg(source_row_sha256,chr(10) ORDER BY bar_ts),'UTF8')),'hex') INTO n,source_n,mismatch_n,hash_n,identity_n,scope_n,duplicate_n,flags_n,null_n,first_bar,last_bar,raw_digest FROM checked;
 SELECT count(*) INTO retained_n FROM market_fixed_20250901_20260831.alpaca_sip_bars_1m_202608 WHERE instrument_key=m.instrument_key AND bar_ts>=lo AND bar_ts<hi AND session_label::text=m.session_label;
 IF n IS DISTINCT FROM m.observed_rows OR n IS DISTINCT FROM retained_n OR source_n IS DISTINCT FROM n OR mismatch_n+hash_n+identity_n+scope_n+duplicate_n+flags_n+null_n<>0 THEN RAISE EXCEPTION 'RETAINED_STAGE_V3_RECONCILIATION_FAILED: typed %, source %, expected %, mismatches %, hashes %, identity %, scope %, duplicate %, flags %, null %',n,source_n,m.observed_rows,mismatch_n,hash_n,identity_n,scope_n,duplicate_n,flags_n,null_n;END IF;
 summary:=jsonb_build_object('manifest_id',m.manifest_id,'manifest_sha256',m.manifest_sha256,'company_id',c.company_id,'source_symbol',c.anchor_ticker,'session_date',m.session_date,'session_label',m.session_label,'observed_source_bars',n,'required_value_fields_checked',n*7,'first_bar',first_bar,'last_bar',last_bar,'row_hash_digest',raw_digest,'identity_record_sha256',encode(d.identity_record_sha256,'hex'),'normalizer_sha256',normalizer_hash,'source_value_linkage_passed',true,'expected_provider_printed_bars',ex.expected_minute_bars,'full_applicable_instrument_population_verified',false,'independent_economic_accuracy_verified',false,'original_historical_receipt_verified',false,'family_accepted',false,'qualification','RETAINED_PARTITION_SOURCE_COPY_AND_DATED_POINT_RECONCILIATION_ONLY');
 IF t.stage='VALIDATE' THEN
  IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_partition p WHERE p.family_id=t.family_id AND p.partition_key=t.partition_key AND p.immutable_input_versions=t.input_versions) THEN RETURN population_top3000_202608_202609_v1.pipeline_validate_v1(p_attempt,p_token);END IF;
  RETURN jsonb_build_object('state','BLOCKED','blocker_code','P02_SOURCE_POPULATION_AND_TEMPORAL_QUALIFICATION_REQUIRED','verified_retained_partition_checks',summary,'resumption_condition',jsonb_build_object('manifest_id',m.manifest_id,'required_action','Create the versioned applicable instrument/session/provider-print population and required independent source/temporal evidence, then requeue this current-version VALIDATE task. Use actual source-index or no-trade evidence; never assume a dense clock or invent unavailable original receipts.','required_stage','SOURCE_EXPECTATION_PARTITION_AND_INDEPENDENT_QUALITY_EVIDENCE','automatic_retry_without_new_evidence',false,'source_copy_checks_passed',true,'family_accepted',false));
 END IF;
 out_digest:=encode(sha256(convert_to(summary::text,'UTF8')),'hex');key:='retained-partition-reconciliation-v3:'||m.manifest_id||':'||out_digest;
 RETURN jsonb_build_object('state','COMPLETE','commit_receipt',jsonb_build_object('commit_key',key,'output_sha256',out_digest,'new_committed_units',1,'unit_kind','SOURCE_LINKAGE_PARTITION_RECONCILIATION_NOT_NEW_PRICE_BARS','immutable_output_ids',jsonb_build_array(m.manifest_id),'input_versions',t.input_versions,'source_reconciliation',summary,'family_accepted',false));
END $body$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.retained_price_stage_v3(uuid,text) FROM PUBLIC,anon,authenticated;